from pyvkteamsclient.stentor.base.client import BaseStentorClient
from pyvkteamsclient.tracer import tracer
from typing import List


class BizMethods(BaseStentorClient):
    @tracer.start_as_current_span("stentor.biz.biz_createUser")
    def biz_createUser(self, email: str, firstName: str, lastName: str, **kwargs):
        """
        Создание нового пользователя
        """
        return self.post(
            headers={"Content-Type": "application/x-www-form-urlencoded"},
            path="api/v1/biz/createUser",
            data={
                "email": email,
                "firstName": firstName,
                "lastName": lastName,
                **kwargs,
            },
        )

    @tracer.start_as_current_span("stentor.biz.biz_changeUser")
    def biz_changeUser(self, email: str, **kwargs):
        """
        Изменение существующего пользователя
        """
        return self.post(
            headers={"Content-Type": "application/x-www-form-urlencoded"},
            path="api/v1/biz/changeUser",
            data={"email": email, **kwargs},
        )

    @tracer.start_as_current_span("stentor.biz.biz_deleteUser")
    def biz_deleteUser(self, email: str):
        """
        Удаление пользователя
        """
        return self.post(
            headers={"Content-Type": "application/x-www-form-urlencoded"},
            path="api/v1/biz/deleteUser",
            data={"email": email},
        )

    @tracer.start_as_current_span("stentor.biz.biz_getUserLastSeen")
    def biz_getUserLastSeen(self, email: str):
        """
        Получение времени последней активности юзера
        """
        return self.post(
            headers={"Content-Type": "application/x-www-form-urlencoded"},
            path="api/v1/biz/getUserLastSeen",
            data={"email": email},
        )

    @tracer.start_as_current_span("stentor.biz.biz_getUsersLastSeenBiz")
    def biz_getUsersLastSeenBiz(self, emails: List[str]):
        """
        Получение времени последней активности набора пользователей
        """
        return self.post(
            headers={"Content-Type": "application/json"}, path="api/v1/biz/getUsersLastSeenBiz", json={"emails": emails}
        )

    @tracer.start_as_current_span("stentor.biz.biz_dropSessions")
    def biz_dropSessions(self, email: str):
        """
        Разлогинить пользователя везде
        """
        return self.post(
            headers={"Content-Type": "application/x-www-form-urlencoded"},
            path="api/v1/biz/dropSessions",
            data={"email": email},
        )

    @tracer.start_as_current_span("stentor.biz.biz_blockUser")
    def biz_blockUser(self, email: str):
        """
        Временная блокировка пользователя без удаления из чатов
        """
        return self.post(
            headers={"Content-Type": "application/x-www-form-urlencoded"},
            path="api/v1/biz/blockUser",
            data={"email": email},
        )

    @tracer.start_as_current_span("stentor.biz.biz_unblockUser")
    def biz_unblockUser(self, email: str):
        """
        Разблокировка пользователя
        """
        return self.post(
            headers={"Content-Type": "application/x-www-form-urlencoded"},
            path="api/v1/biz/unblockUser",
            data={"email": email},
        )

    @tracer.start_as_current_span("stentor.biz.biz_chats")
    def biz_getChats(self, **kwargs):
        """
        Получение списка чатов
        """
        return self.get(path="api/v1/biz/chats", **kwargs)

    @tracer.start_as_current_span("stentor.biz.biz_users")
    def biz_getUsers(self, **kwargs):
        """
        Получение списка пользователей
        """
        return self.get(path="api/v1/biz/users", **kwargs)

    @tracer.start_as_current_span("stentor.biz.biz_users")
    def biz_gpSectionAvailability(self, screenname: str):
        """
        Получение политик доступности разделов и приложений
        """
        return self.get(path="api/v1/biz/gpSectionAvailability", screenname=screenname)
